<?php
require 'config/auth.php'; require 'config/db.php'; require 'config/financial_actions.php';
if (!has_permission('control.view') && !has_permission('control.manage')) { require_permission('control.view'); }
$id=(int)($_GET['id']??$_POST['control_account_id']??0); $unitId=(int)($_SESSION['user']['unit_id']??0); $isAdmin=($_SESSION['user']['role']??'')==='admin'; $userId=(int)($_SESSION['user']['id']??0);
function load_control(mysqli $conn,int $id,int $unitId,bool $isAdmin):?array{$sql='SELECT ca.*,bt.doc_no,bt.doc_date,bt.receive_date,bt.gfmis_date,bt.budget_types,bt.source_fund,bt.expense_category AS original_category,u.unit_code,u.unit_name FROM control_accounts ca LEFT JOIN budget_transfers bt ON bt.id=ca.source_transfer_id LEFT JOIN units u ON u.id=ca.unit_id WHERE ca.id=?'.($isAdmin?'':' AND ca.unit_id=?');$s=$conn->prepare($sql);$isAdmin?$s->bind_param('i',$id):$s->bind_param('ii',$id,$unitId);$s->execute();return $s->get_result()->fetch_assoc()?:null;}
$control=load_control($conn,$id,$unitId,$isAdmin); if(!$control){http_response_code(404);die('ไม่พบบัญชีคุม หรือไม่มีสิทธิ์เข้าถึง');}
$labels=['increase'=>'เงินเพิ่มเดือนนี้','transfer_out'=>'โอนไป','return_army'=>'ส่งคืน ทบ.','carry'=>'กันไว้เบิก','request'=>'ขอใช้','obligation'=>'ผูกพัน','payment'=>'ตัดจ่าย','remittance'=>'นำส่ง'];
if (($_SERVER['REQUEST_METHOD']??'')==='POST') {
    require_permission('control.manage');
    try {
        begin_financial_transaction($conn);
        if (($_POST['action']??'add')==='cancel') {
            $entryId=(int)($_POST['entry_id']??0);
            $s=$conn->prepare('SELECT control_account_id FROM control_account_entries WHERE id=?'); $s->bind_param('i',$entryId); $s->execute();
            if ((int)($s->get_result()->fetch_assoc()['control_account_id']??0)!==$id) throw new RuntimeException('รายการไม่ได้อยู่ในบัญชีที่เลือก',403);
            ledger_void($conn,$entryId,trim($_POST['reason']??''));
        } elseif (($_POST['action']??'add')==='release') {
            $entryId=(int)($_POST['entry_id']??0);
            $s=$conn->prepare('SELECT control_account_id,source_table FROM control_account_entries WHERE id=?');$s->bind_param('i',$entryId);$s->execute();$entry=$s->get_result()->fetch_assoc();
            if(!$entry||(int)$entry['control_account_id']!==$id||$entry['source_table'])throw new RuntimeException('กรุณาปลดวงเงินผ่านเอกสารต้นทาง',403);
            if(mb_strlen(trim($_POST['reason']??''))<5)throw new RuntimeException('กรุณาระบุเหตุผลอย่างน้อย 5 ตัวอักษร');
            ledger_release($conn,$entryId,(string)($_POST['release_date']??''),trim($_POST['reason']));
        } else {
            ledger_add($conn,$id,$_POST['entry_date']??'',$_POST['entry_type']??'',(string)($_POST['amount']??'0'),(int)($_POST['spending_unit_id']??0),trim($_POST['gfmis_code']??''),trim($_POST['activity_code']??''),(int)($_POST['disbursement_no']??0),trim($_POST['expense_category']??''),trim($_POST['note']??''),current_user_id());
        }
        $conn->commit(); header('Location: control_account_detail.php?id='.$id.'&saved=1');exit;
    } catch(Throwable $e) { $conn->rollback();if($e->getCode()===403)http_response_code(403);$entryError=operation_error($e); }
}
$units=$conn->query('SELECT id,unit_code,unit_name FROM units ORDER BY unit_code')->fetch_all(MYSQLI_ASSOC);
$s=$conn->prepare('SELECT e.*,u.unit_code,u.unit_name FROM active_control_entries e LEFT JOIN units u ON u.id=e.spending_unit_id WHERE e.control_account_id=? AND e.amount<>0 ORDER BY e.entry_date,e.id');$s->bind_param('i',$id);$s->execute();$entries=$s->get_result()->fetch_all(MYSQLI_ASSOC);
$sum=ledger_totals($conn,$id);$remaining=ledger_balance($control['received_amount'],$sum);$available=ledger_available_cents($control['received_amount'],$sum)/100;
?>
<!DOCTYPE html><html lang="th"><head><meta name="viewport" content="width=device-width, initial-scale=1"><meta charset="UTF-8"><title>รายละเอียดบัญชีคุม</title><link rel="stylesheet" href="assets/css/style.css?v=<?= filemtime(__DIR__ . '/assets/css/style.css') ?>"></head><body><?php require 'template/nav.php';?><main class="container">
<section class="panel"><div class="toolbar"><div><h1 class="page-title"><?=htmlspecialchars($control['budget_code'])?></h1><p class="page-subtitle"><?=htmlspecialchars($control['item_name'])?></p></div><a class="btn btn-outline" href="control_accounts.php?year=<?=(int)$control['fiscal_year']?>">กลับบัญชีคุม</a><a class="btn btn-primary" href="transactions.php?year=<?=(int)$control['fiscal_year']?>&account_id=<?=$id?>">เพิ่มรายการการเงินในบัญชีนี้</a><?php if($control['source_transfer_id']):?><a class="btn btn-success" href="exports/export_budget.php?id=<?=(int)$control['source_transfer_id']?>">Export ทบ.500-001</a><?php endif;?></div><?php if(isset($_GET['saved'])):?><div class="alert alert-success">บันทึกรายการเรียบร้อยแล้ว</div><?php endif;?><?php if(!empty($entryError)):?><div class="alert alert-danger"><?=htmlspecialchars($entryError)?></div><?php endif;?>
<div class="form-grid form-grid-2"><strong>ปีงบประมาณ</strong><span><?=(int)$control['fiscal_year']?></span><strong>เลขที่เอกสาร</strong><span><?=htmlspecialchars((string)$control['doc_no'])?></span><strong>หน่วยเจ้าของงบ</strong><span><?=htmlspecialchars($control['unit_code'].' - '.$control['unit_name'])?></span><strong>รหัส GFMIS</strong><span><?=htmlspecialchars($control['gfmis_code'])?></span><strong>รหัสกิจกรรมหลัก</strong><span><?=htmlspecialchars($control['activity_code'])?></span><strong>งวดสั่งจ่าย</strong><span><?=htmlspecialchars($control['installment_no'])?></span><strong>ประเภทงบ</strong><span><?=htmlspecialchars((string)$control['budget_types'])?></span><strong>วงเงินที่ได้รับ</strong><span><?=number_format((float)$control['received_amount'],2)?> บาท</span><strong>คงเหลือ</strong><span><b><?=number_format($remaining,2)?> บาท</b></span></div></section>
<?php if(has_permission('control.manage')):?><section class="panel"><h2>เพิ่มรายการเบิก/เคลื่อนไหว</h2><form method="post"><?=csrf_field()?><?=request_field()?><input type="hidden" name="control_account_id" value="<?=$id?>"><div class="form-grid form-grid-2"><label>วันที่รายการ *</label><input type="date" name="entry_date" required><label>รหัส GFMIS *</label><input name="gfmis_code" value="<?=htmlspecialchars($control['gfmis_code'])?>" required><label>รหัสกิจกรรมหลัก *</label><input name="activity_code" value="<?=htmlspecialchars($control['activity_code'])?>" required><label>เบิกครั้งที่ *</label><input type="number" name="disbursement_no" min="1" required><label>ประเภทรายการ *</label><select name="entry_type" required><?php foreach($labels as $k=>$v):?><option value="<?=$k?>"><?=$v?></option><?php endforeach;?></select><label>จำนวนเงิน *</label><input type="number" name="amount" min="0.01" step="0.01" required><label>หน่วยผู้เบิก *</label><select name="spending_unit_id" required><?php foreach($units as $u):?><option value="<?=(int)$u['id']?>" <?=(int)$u['id']===(int)$control['unit_id']?'selected':''?>><?=htmlspecialchars($u['unit_code'].' - '.$u['unit_name'])?></option><?php endforeach;?></select><label>หมวดเงิน (ตามบัญชีคุมงบประมาณ)</label><?php $categorySnapshot=classification_get($conn,$id); ?><select name="expense_category"><option value="<?=htmlspecialchars((string)($categorySnapshot['expense_code']??$control['original_category']))?>"><?=htmlspecialchars((string)($categorySnapshot['expense_code']??$control['original_category']).' · '.($categorySnapshot['expense_name']??'หมวดเงินเดิม'))?></option></select><label>หมายเหตุ</label><input name="note" placeholder="ค่าอะไร / รายละเอียดเพิ่มเติม"></div><div class="toolbar" style="margin-top:14px"><button class="btn btn-success">บันทึกรายการ</button></div></form></section><?php endif;?>
<section class="panel"><h2>รายการเคลื่อนไหวทั้งหมด</h2><p>วงเงินที่ใช้ได้หลังหักยอดสงวน <?=number_format($available,2)?> บาท · <a href="audit_history.php?entity=control_account_entries">ดูประวัติการแก้ไข/ยกเลิก</a></p><div class="table-wrap"><table><thead><tr><th>วันที่</th><th>เลขที่/ครั้งที่เบิก</th><th>ประเภท</th><th class="text-right">จำนวนเงิน</th><th>หน่วยผู้เบิก</th><th>หมวดเงิน</th><th>หมายเหตุ</th><th>จัดการ</th></tr></thead><tbody><?php if(!$entries):?><tr><td colspan="8" class="text-center">ยังไม่มีรายการเบิก</td></tr><?php endif;?><?php foreach($entries as $e):?><tr><td><?=htmlspecialchars($e['entry_date'])?></td><td><?=htmlspecialchars($e['disbursement_no'])?></td><td><?=htmlspecialchars($labels[$e['entry_type']]??$e['entry_type'])?></td><td class="text-right"><?=number_format((float)$e['amount'],2)?></td><td><?=htmlspecialchars($e['unit_code'].' '.$e['unit_name'])?></td><td><?=htmlspecialchars((string)$e['expense_category'])?></td><td><?=htmlspecialchars((string)$e['note'])?></td><td><?php if(has_permission('control.manage')):?><a href="<?=htmlspecialchars(financial_entry_url($e,(int)$control['fiscal_year']))?>">แก้ไข / ลบ<?= $e['source_table']?'ที่ต้นทาง':''?></a><?php endif;?><?php if(has_permission('control.manage')&&(int)$e['id']>0&&!$e['source_table']):?><details><summary>ลบ / ปลดวงเงิน</summary><form method="post"><?=csrf_field()?><?=request_field()?><input type="hidden" name="control_account_id" value="<?=$id?>"><input type="hidden" name="entry_id" value="<?=(int)$e['id']?>"><select name="action"><option value="cancel">ลบรายการ</option><?php if(in_array($e['entry_type'],['carry','request','obligation'],true)):?><option value="release">ปลดวงเงิน</option><?php endif;?></select><input name="reason" minlength="5" maxlength="255" placeholder="เหตุผล" required><input type="date" name="release_date" value="<?=date('Y-m-d')?>"><button class="btn btn-danger">ยืนยัน</button></form></details><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
